    if (n <= 0) {
        return 0; // Nessun numero di Fibonacci è meno di 0
    } else if (n == 1) {
        return 1; // Il primo numero di Fibonacci è 1
    } else {
        return fibonacci(n - 1) + fibonacci(n - 2); // Calcolo del numero di Fibonacci successivo
    }
