```cpp
#include <iostream>

// Function to calculate the nth Fibonacci number
int fibonacci(int n) {
    // Base cases
    if (n <= 0) {
        return 0;
    } else if (n == 1) {
        return 1;
    } else {
        // Recursive case
        return fibonacci(n - 1) + fibonacci(n - 2);
    }
}

