However, please note that this recursive implementation has a time complexity of O(2^n), which can be inefficient for large values of n. A more efficient approach would be to use dynamic programming to store and reuse previously calculated Fibonacci numbers.

Here's an optimized version of the program using dynamic programming:

```cpp
#include <iostream>

// Function to calculate the nth Fibonacci number
int fibonacci(int n) {
    // Base cases
    if (n <= 0) {
        return 0;
    } else if (n == 1) {
        return 1;
    }

    // Create an array to store Fibonacci numbers
    int fib[n + 1];

    // Initialize the first two Fibonacci numbers
    fib[1] = 1;
    if (n > 1) {
        fib[2] = fib[1] + fib[0];
    }

    // Calculate Fibonacci numbers iteratively
    for (int i = 3; i <= n; i++) {
        fib[i] = fib[i - 1] + fib[i - 2];
    }

    // Return the nth Fibonacci number
    return fib[n];
}

int main() {
    int n;
    std::cout << "Enter a positive integer: ";
    std::cin >> n;

    // Check if n is a positive integer
    if (n <= 0) {
        std::cout << "Please enter a positive integer." << std::endl;
        return 1;
    }

    // Calculate and display the nth Fibonacci number
    int result = fibonacci(n);
    std::cout << "The " << n << "th Fibonacci number is: " << result << std::endl;

    return 0;
}
```

This optimized version has a time complexity of O(n), making it much more efficient for large values of n.

